const { readFileSync, writeFileSync } = await import('fs');
const { join } = await import('path');
const { execFileSync } = await import('child_process');
const parseCliJson = (raw) => {
  const start = raw.indexOf('{');
  if (start === -1) throw new Error('JSON payload not found');
  return JSON.parse(raw.slice(start));
};
const filePath = join($root, 'packages/main/src/handlers/test-auto.ts');
const original = readFileSync(filePath, 'utf8');
const from = '@test test-auto-guardrails';
const to = '@test temporary-gap-edge';
