writeFileSync(filePath, original.replace(from, to), 'utf8');
try {
  const raw = execFileSync('koala', ['gap_analyze', '--format=json'], { cwd: $root, encoding: 'utf8' });
  const data = parseCliJson(raw);
  const tempGapCount = data.gaps.filter(g => String(g.description || '').includes('tests/fixtures/temporary-gap-edge.json')).length;
  const storeGapCount = data.gaps.filter(g => String(g.description || '').includes('store-state-entries.json')).length;
  return { tempGapCount, storeGapCount };
} finally {
  writeFileSync(filePath, original, 'utf8');
}

const { readFileSync, writeFileSync } = await import('fs');
const { join } = await import('path');
const { execFileSync } = await import('child_process');
const parseCliJson = (raw) => {
  const start = raw.indexOf('{');
  if (start === -1) throw new Error('JSON payload not found');
  return JSON.parse(raw.slice(start));
};
const filePath = join($root, 'packages/main/src/core/store.ts');
const original = readFileSync(filePath, 'utf8');
const marker = '   * @test store-state-entries';
const mutated = original.split(marker + '\n').join('');
if (mutated === original) throw new Error('store @test lines not found');
writeFileSync(filePath, mutated, 'utf8');
try {
  const raw = execFileSync('koala', ['gap_analyze', '--format=json'], { cwd: $root, encoding: 'utf8' });
  const data = parseCliJson(raw);
  const missing = data.gaps.filter(g => {
    const d = String(g.description || '');
    return d.includes('函数 readStory 缺少 @test 注释')
      || d.includes('函数 writeStory 缺少 @test 注释')
      || d.includes('函数 readBugs 缺少 @test 注释')
      || d.includes('函数 writeBugs 缺少 @test 注释')
      || d.includes('函数 readTestEvidence 缺少 @test 注释')
      || d.includes('函数 writeTestEvidence 缺少 @test 注释');
  }).length;
  return { missing };
} finally {
  writeFileSync(filePath, original, 'utf8');
}
